export function pixelText(ctx,str,x,y,size=2,color='#ffe7b5',align='left',shadow=true){str=String(str).toUpperCase();const width=str.length*6*size;if(align==='center')x-=width/2;if(align==='right')x-=width;const draw=(ox,oy,c)=>{ctx.fillStyle=c;for(let i=0;i<str.length;i++){let g=GLYPHS[str[i]];if(!g)continue;for(let p=0;p<35;p++)if(g[p]==='1')ctx.fillRect(Math.round(x+i*6*size+p%5*size+ox),Math.round(y+Math.floor(p/5)*size+oy),size,size);}};if(shadow)draw(size,size,'#1b102b');draw(0,0,color);}
