 costumeImage(name,stage){const key=name+stage;if(!stage)return this.images[name];if(this.costumes.has(key))return this.costumes.get(key);const source=this.images[name];if(!source)return source;const can=document.createElement('canvas');can.width=source.width;can.height=source.height;const ctx=can.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0);const data=ctx.getImageData(0,0,can.width,can.height),px=data.data;const lavender=[[1,1,1],[1.08,.92,1.02],[.86,.91,1.08],[1.1,.95,.96],[1.06,.89,1.06],[1.12,.82,.97],[.82,1.07,1.04],[1.08,1.05,1.02]][stage];for(let i=0;i<px.length;i+=4){if(px[i+3]<180)continue;const r=px[i],g=px[i+1],b=px[i+2],x=(i/4)%can.width,y=Math.floor(i/4/can.width);if(b>r+18&&g>r+7&&r>80){const stripe=(Math.floor(y/(stage===4?12:24))+Math.floor(x/(stage===4?12:500)))%2;const k=stripe?1:stage===2?.88:stage===6?1.1:.96;px[i]=Math.min(255,r*k);px[i+1]=Math.min(255,g*k);px[i+2]=Math.min(255,b*k);}else if(b>g+10&&r>g+6&&r>85&&b>r-10){px[i]=Math.min(255,r*lavender[0]);px[i+1]=Math.min(255,g*lavender[1]);px[i+2]=Math.min(255,b*lavender[2]);}}ctx.putImageData(data,0,0);if(this.costumes.size>=6)this.costumes.delete(this.costumes.keys().next().value);this.costumes.set(key,can);return can;}
